# Let me analyze the differences more systematically
inputs = ['gjfj', 'hkfcfx', 'iuag', 'hkzz', 'dwxwd']
outputs = ['gjfj', 'hjhfcfx', 'iuag', 'hjhzz', 'uwhxwhu']

print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")
    if inp != outp:
        # Find the difference
        min_len = min(len(inp), len(outp))
        diff_pos = -1
        for j in range(min_len):
            if inp[j] != outp[j]:
                diff_pos = j
                break
        if diff_pos == -1:
            if len(inp) != len(outp):
                diff_pos = min_len
        if diff_pos != -1:
            print(f"  First difference at position {diff_pos}")
            if diff_pos < len(outp):
                print(f"  Character at position {diff_pos} in output: '{outp[diff_pos]}'")
        print(f"  Length change: {len(outp) - len(inp)}")
    print()

